// Parse CISA KEV JSON feed
const data = $input.item.json;

// The vulnerabilities are in the 'vulnerabilities' array
const vulnerabilities = data.vulnerabilities || [];

// Format each vulnerability
const formatted = vulnerabilities.map(vuln => {
  return {
    json: {
      cve_id: vuln.cveID,
      vulnerability_name: vuln.vulnerabilityName,
      vendor: vuln.vendorProject,
      product: vuln.product,
      date_added: vuln.dateAdded,
      due_date: vuln.dueDate,
      required_action: vuln.requiredAction.substring(0, 150) + '...',
      short_description: vuln.shortDescription,
      ransomware: vuln.knownRansomwareCampaignUse,
      notes: vuln.notes || 'No notes',
      cwes: vuln.cwes ? vuln.cwes.join(', ') : 'N/A',
      source: 'CISA KEV'
    }
  };
});

// Return only the most recent 10 CVEs
return formatted.slice(0, 10);

